// A class becomes iterable by defining [Symbol.iterator]()
class Range {
  constructor(start, end) {
    this.start = start;
    this.end = end;
  }
  [Symbol.iterator]() {
    let i = this.start;
    const end = this.end;
    return {
      next() {
        return i < end
          ? { value: i++, done: false }
          : { value: undefined, done: true };
      }
    };
  }
}

const r = new Range(1, 4);
[...r];                    // [1, 2, 3]
Array.from(r);             // [1, 2, 3]
for (const n of r) { /* 1, 2, 3 */ }

